content.css:
.s-curve {
  position: relative;
  overflow: hidden;
  user-select: none;
}
.s-curve svg {
  display: block;
  overflow: hidden;
}
.s-curve text {
  fill-opacity: 1;
}
[data-role="line-label"],
[data-role="column-label"],
[data-role="label-background"],
[data-role="cell-text"],
[data-role="total"],
[data-role="totals-header"],
[data-role="row-line"],
[data-role="column-line"],
[data-role="header-line"],
.s-curve__grid {
  pointer-events: none;
}
.s-curve:focus {
  outline: none;
}
.s-curve__focus-ring {
  position: absolute;
  pointer-events: none;
  border: 2px solid currentColor;
  border-radius: 2px;
  box-sizing: border-box;
}
.s-curve__live {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.s-curve__legend,
.s-curve__chart,
.s-curve__matrix,
.s-curve__scrollbar,
.s-curve__note {
  position: absolute;
}
.s-curve__matrix-body {
  overflow-x: hidden;
}
.s-curve__scrollbar {
  overflow-x: auto;
  overflow-y: hidden;
}
.s-curve__scrollbar-spacer {
  height: 1px;
}
.s-curve__note {
  left: 0;
  right: 0;
  bottom: 2px;
  text-align: center;
}
.s-curve__message {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 16px;
  text-align: center;
}
.s-curve__message-title {
  font-size: 16px;
  font-weight: 600;
}
.s-curve__message-body {
  font-size: 12px;
  max-width: 420px;
}
